import { describe, expect, it } from 'vitest';
import type { Channel } from '../types';
import { channelLcn, findChannelIndexByLcn } from './channel-lcn';

const entries = [7, 9, 13, 75, 802].map(n => ({ channelNumber: n } as Channel));

describe('Montecrestese broadcast numbering', () => {
  it('shows real LCNs instead of the 1-based playlist order', () => {
    expect(entries.map(channelLcn)).toEqual([7, 9, 13, 75, 802]);
  });
  it('tunes sparse LCN 802 even when only five items exist', () => {
    expect(findChannelIndexByLcn(entries, 802)).toBe(4);
    expect(findChannelIndexByLcn(entries, 13)).toBe(2);
    expect(findChannelIndexByLcn(entries, 72)).toBe(-1);
  });
  it('falls back to list position only for unnumbered channels', () => {
    const mixed = [{}, { channelNumber: 13 }, {}] as Channel[];
    expect(findChannelIndexByLcn(mixed, 2)).toBe(-1);
    expect(findChannelIndexByLcn(mixed, 1)).toBe(0);
    expect(findChannelIndexByLcn(mixed, 13)).toBe(1);
    expect(channelLcn({ channelNumber: 0 }, 2)).toBe(3);
  });
  it('prioritizes declared number over an unnumbered positional match', () => {
    const mixed = [{}, { channelNumber: 1 }] as Channel[];
    expect(findChannelIndexByLcn(mixed, 1)).toBe(1);
  });
});
